/**
 * Grsai nano 系列生图: POST /v1/api/generate, replyType=json; 排队时自动轮询 /v1/api/result。
 * images 直接透传画布参考图 (base64 与 url 均可)。
 * params.size 为像素尺寸 (如 1024x1024) 或空; params.quality 为 low/medium/high。
 */
async function grsaiNanoImage({ prompt, images, params: { size, quality, count }, model, http, poll }) {
  const RATIOS = ["1:1", "16:9", "9:16", "4:3", "3:4", "3:2", "2:3", "5:4", "4:5", "21:9"];
  function toRatio(s) {
    if (!s) return "auto";
    if (String(s).indexOf(":") >= 0) return RATIOS.indexOf(s) >= 0 ? s : "auto";
    const m = String(s).match(/^(\\d+)x(\\d+)$/i);
    if (!m) return "auto";
    const t = (+m[1]) / (+m[2]);
    let best = "1:1", diff = 1e9;
    for (const r of RATIOS) {
      const p = r.split(":");
      const d = Math.abs(+p[0] / +p[1] - t);
      if (d < diff) { diff = d; best = r; }
    }
    return best;
  }
  const SIZE = { low: "1K", medium: "2K", high: "4K" };
  const body = { model: model, prompt: prompt, images: images || [], aspectRatio: toRatio(size), imageSize: SIZE[quality] || "1K", replyType: "json" };
  async function collect(data, strict) {
    if (!data) throw new Error("empty response");
    const body = data.data && typeof data.data === "object" ? data.data : data;
    const status = String(body.status || body.state || "").toLowerCase();
    if (status === "succeeded" || status === "succeed" || status === "successful" || status === "success" || status === "completed" || status === "complete" || status === "done" || status === "finished" || status === "ok") {
      const items = body.results || body.urls || [];
      return items.map(function (x) { return x && (x.url || x.video_url || x.file_url || x.oss_url || x.src); }).filter(Boolean);
    }
    if (status === "failed" || status === "error" || status === "violation") throw new Error(body.error || body.failureReason || body.message || status);
    if (strict && !status && body.progress === undefined) throw new Error("unexpected result shape: " + JSON.stringify(data).slice(0, 500));
    return null;
  }
  const n = Math.max(1, Number(count) || 1);
  const urls = [];
  for (let i = 0; i < n; i++) {
    const first = await http.post("/api/generate", body);
    const done = await collect(first);
    if (done) { urls.push.apply(urls, done); continue; }
    if (!first || !first.id) throw new Error("missing task id");
    const final = await poll(
      async function () {
        var data;
        try { data = await http.get("/api/result", { params: { id: first.id } }); }
        catch (e) { if (e && e.response && e.response.data) return collect(e.response.data, true); throw e; }
        try { var pct = data && typeof data.progress === "number" ? data.progress : (data && data.data && typeof data.data.progress === "number" ? data.data.progress : undefined); if (typeof onProgress === "function" && typeof pct === "number") onProgress(pct / 100); } catch (ignored) {}
        return collect(data, true);
      },
      function (result) { return result; },
      { intervalMs: 3000, timeoutMs: 600000 }
    );
    urls.push.apply(urls, final);
  }
  return urls;
}

return await grsaiNanoImage({ prompt, images, params, model, http, poll });

