  }
  const headers = { "Content-Type": "application/json", Authorization: "Bearer " + apiKey };
  const first = await request({ method: "post", url: root + "/v1/api/generate", headers: headers, data: body, timeout: 1200000 });
  let urls = await collect(first);
  if (!urls) {
    if (!first || !first.id) throw new Error("missing task id");
    urls = await poll(
      async function () {
        var data;
        try { data = await http.get("/api/result", { params: { id: first.id } }); }
