/**
 * Grsai 文本: POST /v1/chat/completions (画布默认走 /v1/responses, Grsai 只提供 chat 接口, 故需脚本)。
 * stream=false 一次返回, 通过 onDelta 回显全文。content 数组 (图文混排) 透传。
 */
async function grsaiChat({ messages, model, http, onDelta }) {
  const norm = (messages || []).map(function (m) {
    if (typeof m.content === "string") return { role: m.role, content: m.content };
    const parts = [];
    for (const p of m.content || []) {
      if (typeof p === "string") parts.push({ type: "text", text: p });
      else if (p && p.type === "text") parts.push({ type: "text", text: p.text || "" });
      else if (p && p.type === "image_url") parts.push(p);
      else if (p && p.text) parts.push({ type: "text", text: p.text });
    }
    return { role: m.role, content: parts };
  });
  const data = await http.post("/chat/completions", { model: model, stream: false, messages: norm });
  const content = data && data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content;
  const text = typeof content === "string" ? content : JSON.stringify(content || "");
  onDelta(text);
  return text;
}

return await grsaiChat({ messages, model, http, onDelta });

